-- A receipt is an actual cash movement; a grid entry only records tuition coverage.
ALTER TABLE student_payments ADD COLUMN payment_kind TEXT NOT NULL DEFAULT 'receipt'
  CHECK(payment_kind IN ('receipt','coverage'));
ALTER TABLE student_payments ADD COLUMN covered_through_month TEXT;

CREATE TABLE payment_coverage_reclassifications (
  payment_id INTEGER PRIMARY KEY,
  internal_folio TEXT NOT NULL,
  original_paid_at TEXT NOT NULL,
  amount REAL NOT NULL,
  reason TEXT NOT NULL,
  classified_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Exact signature of receipts generated by the old grid, including its invented date.
INSERT INTO payment_coverage_reclassifications(payment_id,internal_folio,original_paid_at,amount,reason)
SELECT sp.id,sp.folio,sp.paid_at,sp.amount,'Cobertura generada por tabla de colegiaturas; no acredita ingreso a caja'
FROM student_payments sp JOIN students st ON st.id=sp.student_id
WHERE sp.concept_type='tuition' AND sp.payment_method='Administrativo'
  AND sp.covered_month IS NOT NULL AND sp.paid_at=sp.covered_month||'-10'
  AND sp.folio='COL-'||st.student_number||'-'||replace(sp.covered_month,'-','');

UPDATE student_payments SET payment_kind='coverage'
WHERE id IN (SELECT payment_id FROM payment_coverage_reclassifications);
CREATE INDEX idx_student_payments_cash_date ON student_payments(payment_kind,paid_at);
CREATE INDEX IF NOT EXISTS idx_tuition_charges_payment ON student_tuition_charges(payment_id);
